void ContentBlock::DestroyActive() {
  switch (tag_) {

    case Tag::kImageContentBlock:
      std::destroy_at(&data_.image_content_block);
      break;
    case Tag::kTextContentBlock:
      std::destroy_at(&data_.text_content_block);
      break;
    case Tag::kFileContentBlock:
      std::destroy_at(&data_.file_content_block);
      break;
    case Tag::kFileExtractedTextContentBlock:
      std::destroy_at(&data_.file_extracted_text_content_block);
      break;
    case Tag::kPageExcerptContentBlock:
      std::destroy_at(&data_.page_excerpt_content_block);
      break;
    case Tag::kPageTextContentBlock:
      std::destroy_at(&data_.page_text_content_block);
      break;
    case Tag::kVideoTranscriptContentBlock:
      std::destroy_at(&data_.video_transcript_content_block);
      break;
    case Tag::kRequestTitleContentBlock:
      std::destroy_at(&data_.request_title_content_block);
      break;
    case Tag::kChangeToneContentBlock:
      std::destroy_at(&data_.change_tone_content_block);
      break;
    case Tag::kMemoryContentBlock:
      std::destroy_at(&data_.memory_content_block);
      break;
    case Tag::kFilterTabsContentBlock:
      std::destroy_at(&data_.filter_tabs_content_block);
      break;
    case Tag::kSuggestFocusTopicsContentBlock:
      std::destroy_at(&data_.suggest_focus_topics_content_block);
      break;
    case Tag::kSuggestFocusTopicsWithEmojiContentBlock:
      std::destroy_at(&data_.suggest_focus_topics_with_emoji_content_block);
      break;
    case Tag::kReduceFocusTopicsContentBlock:
      std::destroy_at(&data_.reduce_focus_topics_content_block);
      break;
    case Tag::kWebSourcesContentBlock:
      std::destroy_at(&data_.web_sources_content_block);
      break;
    case Tag::kSimpleRequestContentBlock:
      std::destroy_at(&data_.simple_request_content_block);
      break;
  }
}

